create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key,full_name text not null,email text unique not null,employee_no text,job_title text,role text not null check(role in('admin','director','coordinator','visitor')),department text,is_active boolean default true,created_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,is_active boolean default true,created_at timestamptz default now());
create table if not exists rotation_requests(id uuid primary key default gen_random_uuid(),cycle_name text not null,start_date date,end_date date,instructions text,status text default 'requested',created_by uuid references profiles(id),assigned_coordinator uuid references profiles(id),created_at timestamptz default now());
create table if not exists rotation_plans(id uuid primary key default gen_random_uuid(),request_id uuid references rotation_requests(id) on delete cascade,version_no int default 1,status text default 'draft',submitted_by uuid references profiles(id),approved_by uuid references profiles(id),submitted_at timestamptz,approved_at timestamptz,created_at timestamptz default now());
create table if not exists rotation_assignments(id uuid primary key default gen_random_uuid(),plan_id uuid references rotation_plans(id) on delete cascade,project_id uuid references projects(id),assigned_director uuid references profiles(id),visit_date date not null,end_date date,priority text default 'normal',instructions text,status text default 'scheduled',check_in_at timestamptz,completed_at timestamptz,created_at timestamptz default now());
create table if not exists daily_notes(id uuid primary key default gen_random_uuid(),assignment_id uuid references rotation_assignments(id) on delete cascade,author_id uuid references profiles(id),note_date date default current_date,note text not null,progress int default 0 check(progress between 0 and 100),created_at timestamptz default now());
create table if not exists visit_reports(id uuid primary key default gen_random_uuid(),assignment_id uuid references rotation_assignments(id) on delete cascade,submitted_by uuid references profiles(id),summary text,findings text,recommendations text,status text default 'draft',submitted_at timestamptz,reviewed_at timestamptz,created_at timestamptz default now());
create table if not exists consolidated_reports(id uuid primary key default gen_random_uuid(),plan_id uuid references rotation_plans(id),created_by uuid references profiles(id),title text not null,summary text,status text default 'draft',submitted_at timestamptz,created_at timestamptz default now());
create table if not exists consolidated_report_items(report_id uuid references consolidated_reports(id) on delete cascade,visit_report_id uuid references visit_reports(id) on delete cascade,primary key(report_id,visit_report_id));
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),title text not null,message text,is_read boolean default false,created_at timestamptz default now());
create table if not exists audit_log(id bigint generated always as identity primary key,user_id uuid references profiles(id),action text not null,entity_type text,entity_id uuid,details jsonb,created_at timestamptz default now());
alter table profiles enable row level security;alter table rotation_requests enable row level security;alter table rotation_plans enable row level security;alter table rotation_assignments enable row level security;alter table daily_notes enable row level security;alter table visit_reports enable row level security;